/* Aurora v2 - anti-aliased font atlas renderer.
 *
 * The atlas is generated by tools/fontgen.py and embedded as a read-only
 * binary. Keeping the parser small and bounds-checked is intentional: it will
 * also be used by the user-space compositor for untrusted UI assets later.
 */
#include <string.h>
#include <ui/font.h>

#define FONT_MAGIC 0x46525541u
#define FONT_VERSION 1u

typedef struct __attribute__((packed)) {
    uint32_t magic;
    uint32_t version;
    uint32_t face_count;
    uint32_t face_offset;
} font_header_t;

typedef struct __attribute__((packed)) {
    uint32_t size;
    uint16_t weight;
    uint16_t glyph_count;
    int16_t ascent;
    int16_t descent;
    uint32_t glyph_offset;
    uint32_t atlas_offset;
    uint16_t atlas_width;
    uint16_t atlas_height;
    uint16_t line_height;
    uint16_t reserved;
} font_face_t;

typedef struct __attribute__((packed)) {
    uint32_t codepoint;
    int16_t left;
    int16_t top;
    uint16_t width;
    uint16_t height;
    uint16_t advance;
    uint16_t atlas_x;
    uint16_t atlas_y;
} font_glyph_t;

static bool range_valid(size_t size, uint64_t offset, uint64_t length)
{
    return offset <= size && length <= size - offset;
}

static const font_face_t *face_at(const ui_font_t *font, uint32_t index);

static bool validate_font(const ui_font_t *font)
{
    const font_header_t *header = (const font_header_t *)font->data;

    for (uint32_t face_index = 0; face_index < header->face_count; face_index++) {
        const font_face_t *face = face_at(font, face_index);
        if (face->glyph_count == 0 || face->atlas_width == 0 || face->atlas_height == 0) {
            return false;
        }
        if (!range_valid(font->size, face->glyph_offset,
                         (uint64_t)face->glyph_count * sizeof(font_glyph_t)) ||
            !range_valid(font->size, face->atlas_offset,
                         (uint64_t)face->atlas_width * face->atlas_height)) {
            return false;
        }

        const font_glyph_t *glyphs = (const font_glyph_t *)(font->data + face->glyph_offset);
        uint32_t previous_codepoint = 0;
        for (uint32_t glyph_index = 0; glyph_index < face->glyph_count; glyph_index++) {
            const font_glyph_t *glyph = &glyphs[glyph_index];
            if (glyph_index != 0 && glyph->codepoint < previous_codepoint) {
                return false;
            }
            previous_codepoint = glyph->codepoint;
            if ((uint32_t)glyph->atlas_x + glyph->width > face->atlas_width ||
                (uint32_t)glyph->atlas_y + glyph->height > face->atlas_height) {
                return false;
            }
        }
    }
    return true;
}

bool ui_font_init(ui_font_t *font, const void *data, size_t size)
{
    if (font == NULL || data == NULL || size < sizeof(font_header_t)) {
        return false;
    }
    const font_header_t *header = data;
    if (header->magic != FONT_MAGIC || header->version != FONT_VERSION || header->face_count == 0 ||
        header->face_count > 64) {
        return false;
    }
    if (!range_valid(size, header->face_offset,
                     (uint64_t)header->face_count * sizeof(font_face_t))) {
        return false;
    }
    font->data = data;
    font->size = size;
    font->scale = 1;
    return validate_font(font);
}

static const font_face_t *face_at(const ui_font_t *font, uint32_t index)
{
    const font_header_t *header = (const font_header_t *)font->data;
    return (const font_face_t *)(font->data + header->face_offset + index * sizeof(font_face_t));
}

static const font_face_t *find_face(const ui_font_t *font, uint32_t size, uint16_t weight)
{
    const font_header_t *header = (const font_header_t *)font->data;
    const font_face_t *best = NULL;
    unsigned best_score = 0xFFFFFFFFu;

    for (uint32_t index = 0; index < header->face_count; index++) {
        const font_face_t *face = face_at(font, index);
        if (face->size == size && face->weight == weight) {
            return face;
        }
        unsigned size_delta = face->size > size ? face->size - size : size - face->size;
        unsigned weight_delta =
            face->weight > weight ? face->weight - weight : weight - face->weight;
        unsigned score = size_delta * 1024u + weight_delta;
        if (score < best_score) {
            best_score = score;
            best = face;
        }
    }
    return best;
}

static const font_glyph_t *find_glyph(const ui_font_t *font, const font_face_t *face,
                                      uint32_t codepoint)
{
    uint32_t low = 0;
    uint32_t high = face->glyph_count;

    const font_glyph_t *glyphs = (const font_glyph_t *)(font->data + face->glyph_offset);
    while (low < high) {
        uint32_t middle = low + (high - low) / 2;
        if (glyphs[middle].codepoint < codepoint) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if (low < face->glyph_count && glyphs[low].codepoint == codepoint) {
        return &glyphs[low];
    }
    return NULL;
}

static uint32_t next_codepoint(const char **cursor)
{
    const unsigned char *text = (const unsigned char *)*cursor;
    uint32_t codepoint;

    if (text[0] < 0x80) {
        *cursor += 1;
        return text[0];
    }
    if ((text[0] & 0xE0) == 0xC0 && text[1] != 0) {
        codepoint = ((uint32_t)(text[0] & 0x1F) << 6) | (uint32_t)(text[1] & 0x3F);
        *cursor += 2;
        return codepoint;
    }
    if ((text[0] & 0xF0) == 0xE0 && text[1] != 0 && text[2] != 0) {
        codepoint = ((uint32_t)(text[0] & 0x0F) << 12) | ((uint32_t)(text[1] & 0x3F) << 6) |
                    (uint32_t)(text[2] & 0x3F);
        *cursor += 3;
        return codepoint;
    }
    if ((text[0] & 0xF8) == 0xF0 && text[1] != 0 && text[2] != 0 && text[3] != 0) {
        codepoint = ((uint32_t)(text[0] & 0x07) << 18) | ((uint32_t)(text[1] & 0x3F) << 12) |
                    ((uint32_t)(text[2] & 0x3F) << 6) | (uint32_t)(text[3] & 0x3F);
        *cursor += 4;
        return codepoint;
    }
    *cursor += 1;
    return 0xFFFD;
}

static const font_glyph_t *glyph_for(const ui_font_t *font, const font_face_t *face,
                                     uint32_t codepoint)
{
    const font_glyph_t *glyph = find_glyph(font, face, codepoint);
    if (glyph == NULL) {
        glyph = find_glyph(font, face, '?');
    }
    return glyph;
}

uint32_t ui_font_text_width(const ui_font_t *font, uint32_t size, uint16_t weight, const char *text)
{
    if (font == NULL || font->data == NULL || text == NULL) {
        return 0;
    }
    const font_face_t *face = find_face(font, size * (font->scale == 2 ? 2 : 1), weight);
    if (face == NULL) {
        return 0;
    }

    uint32_t width = 0;
    while (*text != '\0') {
        uint32_t codepoint = next_codepoint(&text);
        const font_glyph_t *glyph = glyph_for(font, face, codepoint);
        if (glyph != NULL) {
            width += glyph->advance;
        }
    }
    return (width + (font->scale == 2 ? 1 : 0)) / (font->scale == 2 ? 2 : 1);
}

uint32_t ui_font_line_height(const ui_font_t *font, uint32_t size, uint16_t weight)
{
    if (font == NULL || font->data == NULL) {
        return 0;
    }
    const font_face_t *face = find_face(font, size * (font->scale == 2 ? 2 : 1), weight);
    return face != NULL ? face->line_height / (font->scale == 2 ? 2 : 1) : 0;
}

void ui_font_draw(const ui_font_t *font, const ui_surface_t *surface, uint32_t size,
                  uint16_t weight, int x, int y, const char *text, uint8_t red, uint8_t green,
                  uint8_t blue, uint8_t alpha)
{
    if (font == NULL || font->data == NULL || surface == NULL || text == NULL || alpha == 0) {
        return;
    }
    ui_surface_t physical = ui_physical(surface);
    unsigned scale = ui_scale(surface);
    size *= scale;
    x *= (int)scale;
    y *= (int)scale;
    surface = &physical;
    const font_face_t *face = find_face(font, size, weight);
    if (face == NULL) {
        return;
    }
    if (!range_valid(font->size, face->glyph_offset,
                     (uint64_t)face->glyph_count * sizeof(font_glyph_t)) ||
        !range_valid(font->size, face->atlas_offset,
                     (uint64_t)face->atlas_width * face->atlas_height)) {
        return;
    }

    const uint8_t *atlas = font->data + face->atlas_offset;
    int pen_x = x;

    while (*text != '\0') {
        uint32_t codepoint = next_codepoint(&text);
        const font_glyph_t *glyph = glyph_for(font, face, codepoint);
        if (glyph == NULL) {
            continue;
        }
        int glyph_x = pen_x + glyph->left;
        int glyph_y = y + glyph->top;
        if (glyph_x + glyph->width <= surface->clip_x0 ||
            glyph_y + glyph->height <= surface->clip_y0 || glyph_x >= surface->clip_x1 ||
            glyph_y >= surface->clip_y1) {
            pen_x += glyph->advance;
            continue;
        }

        for (uint16_t row = 0; row < glyph->height; row++) {
            int destination_y = glyph_y + (int)row;
            if (destination_y < surface->clip_y0 || destination_y >= surface->clip_y1) {
                continue;
            }
            for (uint16_t column = 0; column < glyph->width; column++) {
                int destination_x = glyph_x + (int)column;
                if (destination_x < surface->clip_x0 || destination_x >= surface->clip_x1) {
                    continue;
                }
                uint8_t coverage = atlas[(uint32_t)(glyph->atlas_y + row) * face->atlas_width +
                                         glyph->atlas_x + column];
                if (coverage == 0) {
                    continue;
                }
                uint32_t source_alpha = (uint32_t)coverage * alpha / 255u;
                uint32_t *pixel = &surface->pixels[(uint32_t)destination_y * surface->stride +
                                                   (uint32_t)destination_x];
                uint32_t destination = *pixel;
                uint8_t destination_red = (uint8_t)((destination >> surface->red_shift) & 0xFF);
                uint8_t destination_green = (uint8_t)((destination >> surface->green_shift) & 0xFF);
                uint8_t destination_blue = (uint8_t)((destination >> surface->blue_shift) & 0xFF);
                uint32_t inverse = 255u - source_alpha;
                uint8_t mixed_red =
                    (uint8_t)((red * source_alpha + destination_red * inverse) / 255u);
                uint8_t mixed_green =
                    (uint8_t)((green * source_alpha + destination_green * inverse) / 255u);
                uint8_t mixed_blue =
                    (uint8_t)((blue * source_alpha + destination_blue * inverse) / 255u);
                *pixel = ((uint32_t)mixed_red << surface->red_shift) |
                         ((uint32_t)mixed_green << surface->green_shift) |
                         ((uint32_t)mixed_blue << surface->blue_shift);
            }
        }
        pen_x += glyph->advance;
    }
}
